from PIL import Image
from io import BytesIO


def create_thumbnail(image_data, size, format='WEBP'):
    """
    Create a center-cropped thumbnail from image data

    Args:
        image_data: Raw image data (bytes)
        size: Tuple of (width, height) for thumbnail size
        format: Output format (WEBP, JPEG, PNG, etc.)

    Returns:
        BytesIO object containing the thumbnail data
    """
    try:
        # Open image from bytes
        image = Image.open(BytesIO(image_data))

        # Convert to RGB if necessary (for WebP output)
        if format == 'WEBP' and image.mode in ('RGBA', 'LA', 'P'):
            # For WebP, we can preserve transparency or convert to RGB
            if image.mode == 'P':
                image = image.convert('RGBA')
            # Keep RGBA for WebP to preserve transparency
        elif format == 'JPEG' and image.mode in ('RGBA', 'LA', 'P'):
            # Create a white background for JPEG
            background = Image.new('RGB', image.size, (255, 255, 255))
            if image.mode == 'P':
                image = image.convert('RGBA')
            background.paste(image, mask=image.split()[-1] if image.mode == 'RGBA' else None)
            image = background

        # Get target dimensions
        target_width, target_height = size

        # Calculate the aspect ratio of the original image
        original_width, original_height = image.size
        original_ratio = original_width / original_height
        target_ratio = target_width / target_height

        # Determine how to resize and crop
        if original_ratio > target_ratio:
            # Image is wider than target ratio, crop width
            new_height = target_height
            new_width = int(target_height * original_ratio)
        else:
            # Image is taller than target ratio, crop height
            new_width = target_width
            new_height = int(target_width / original_ratio)

        # Resize the image to the calculated dimensions
        image = image.resize((new_width, new_height), Image.Resampling.LANCZOS)

        # Calculate crop box for center cropping
        left = (new_width - target_width) // 2
        top = (new_height - target_height) // 2
        right = left + target_width
        bottom = top + target_height

        # Crop the image to the exact target size
        image = image.crop((left, top, right, bottom))

        # Save to BytesIO
        output = BytesIO()
        if format == 'WEBP':
            image.save(output, format=format, quality=85, optimize=True, method=6)
        else:
            image.save(output, format=format, quality=85, optimize=True)
        output.seek(0)

        return output

    except Exception as e:
        raise Exception(f"Failed to create thumbnail: {str(e)}")


def migrate_post_images(apps, schema_editor):
    """
    Migrate post images from post.image field to file table.
    This function extracts image information from post.image URLs and creates corresponding file records.
    Also checks if files exist in MinIO and copies them to uploads folder if needed.
    """
    Post = apps.get_model('post', 'Post')
    File = apps.get_model('file', 'File')

    print("🚀 Starting Post Image Migration")
    print("=" * 50)

    # Initialize MinIO client
    try:
        minio_client = Minio(
            settings.MINIO_STORAGE_ENDPOINT,
            access_key=settings.MINIO_STORAGE_ACCESS_KEY,
            secret_key=settings.MINIO_STORAGE_SECRET_KEY,
            secure=settings.MINIO_STORAGE_USE_HTTPS
        )
        bucket_name = settings.MINIO_STORAGE_BUCKET_NAME
        print(f"✅ Connected to MinIO bucket: {bucket_name}")
    except Exception as e:
        print(f"❌ Failed to connect to MinIO: {str(e)}")
        return

    # Get posts with image URLs
    posts_with_images = Post.objects.filter(
        image__isnull=False,
        image__gt=''
    ).select_related('author')

    total_posts = posts_with_images.count()
    print(f"📊 Found {total_posts} posts with image data")

    if total_posts == 0:
        print("✅ No posts to migrate")
        return

    migrated_count = 0
    skipped_count = 0
    error_count = 0
    already_in_uploads = 0
    already_in_database = 0
    not_webp = 0
    not_found_in_user_folder = 0

    # Process each post
    for i, post in enumerate(posts_with_images, 1):
        if i % 50 == 0:  # Progress indicator every 50 posts
            print(f"⏳ Processing post {i}/{total_posts}...")

        try:
            # Validate image URL
            if not post.image or not isinstance(post.image, str):
                skipped_count += 1
                continue

            # Extract image name from URL
            image_name = post.image.split('/')[-1]
            if not image_name or '.' not in image_name:
                skipped_count += 1
                continue

            # Only process WebP images
            if not image_name.lower().endswith('.webp'):
                print(f"⏭️  Skipping non-WebP image: {image_name}")
                not_webp += 1
                continue

            # Check if file already exists in database (by URL or by name)
            from django.db import models
            existing_file = File.objects.filter(
                models.Q(url=post.image) | models.Q(name=image_name)
            ).first()

            if existing_file:
                print(f"⏭️  File already exists in database: {image_name}")
                already_in_database += 1
                continue

            # Check if file exists in MinIO and copy from user folder to uploads folder
            uploads_path = f"uploads/{image_name}"
            user_folder_path = f"user_{post.author.id}/{image_name}"

            # Check if file is already in the main uploads folder
            try:
                minio_client.stat_object(bucket_name, uploads_path)
                # File already exists in uploads folder, no need to copy
                print(f"✅ File already in uploads folder: {image_name}")
                already_in_uploads += 1
                # Continue to create File record even if file is already in uploads
            except S3Error:
                # File not in uploads folder, check if it exists in user folder
                try:
                    minio_client.stat_object(bucket_name, user_folder_path)
                    # File exists in user folder, copy it to uploads folder
                    try:
                        from minio.commonconfig import CopySource
                        minio_client.copy_object(
                            bucket_name,
                            uploads_path,
                            CopySource(bucket_name, user_folder_path)
                        )
                        print(f"📁 Copied {user_folder_path} to {uploads_path}")

                        # Generate thumbnails for the copied file
                        try:
                            # Download the file to create thumbnails
                            with tempfile.NamedTemporaryFile() as temp_file:
                                minio_client.fget_object(bucket_name, uploads_path, temp_file.name)

                                # Read the file data
                                with open(temp_file.name, 'rb') as f:
                                    image_data = f.read()

                                # Define thumbnail sizes and their corresponding folders
                                thumbnail_configs = [
                                    {"size": (30, 30), "folder": "uploads/thumbnails/30x30"},
                                    {"size": (300, 300), "folder": "uploads/thumbnails/300x300"}
                                ]

                                for config in thumbnail_configs:
                                    width, height = config["size"]
                                    folder = config["folder"]

                                    try:
                                        # Create thumbnail
                                        thumbnail_data = create_thumbnail(
                                            image_data,
                                            (width, height),
                                            format='WEBP'
                                        )

                                        # Upload thumbnail to MinIO
                                        thumbnail_path = f"{folder}/{image_name}"
                                        minio_client.put_object(
                                            bucket_name,
                                            thumbnail_path,
                                            thumbnail_data,
                                            thumbnail_data.getbuffer().nbytes
                                        )
                                        print(f"🖼️  Created {width}x{height} thumbnail: {thumbnail_path}")

                                    except Exception as thumb_error:
                                        print(f"❌ Failed to create {width}x{height} thumbnail: {str(thumb_error)}")
                                        continue

                        except Exception as thumb_gen_error:
                            print(f"❌ Failed to generate thumbnails for {image_name}: {str(thumb_gen_error)}")
                            # Continue with file creation even if thumbnails fail

                    except Exception as copy_error:
                        print(f"❌ Failed to copy {user_folder_path} to {uploads_path}: {str(copy_error)}")
                        skipped_count += 1
                        continue
                except S3Error:
                    # File not found in user folder either
                    print(f"⚠️  File not found in MinIO: {image_name} (checked: {user_folder_path})")
                    not_found_in_user_folder += 1
                    continue

            # Generate proper file URL using the same format as FileUploadView
            minio_endpoint = getattr(settings, 'FILES_CDN_ENDPOINT', '')
            if not minio_endpoint:
                # Fallback to original URL if FILES_CDN_ENDPOINT is not set
                file_url = f"http://api.urbankiff.local/files/{image_name}"
            else:
                file_url = f"{minio_endpoint}/{image_name}"

            # Update post image field with the new file URL
            post.image = file_url
            post.save(update_fields=['image', 'updated_at'])
            print(f"📝 Updated post {post.id} image URL to: {file_url}")

            # Determine MIME type based on file extension
            extension = image_name.lower().split('.')[-1]
            mime_types = {
                'webp': 'image/webp',
            }
            mime_type = mime_types.get(extension, 'image/jpeg')

            # Create file record
            File.objects.create(
                owner=post.author,
                name=image_name,
                path='uploads',
                url=file_url,
                mime_type=mime_type,
                created_at=post.created_at,
                updated_at=post.updated_at
            )

            migrated_count += 1

        except Exception as e:
            print(f"Error processing post {post.id}: {str(e)}")
            error_count += 1
            continue

    # Print summary
    print("\n" + "=" * 60)
    print("📋 MIGRATION SUMMARY")
    print("=" * 60)
    print(f"Total posts processed: {total_posts}")
    print(f"✅ Successfully migrated: {migrated_count}")
    print(f"📁 Already in uploads folder: {already_in_uploads}")
    print(f"🗄️  Already in database: {already_in_database}")
    print(f"🖼️  Non-WebP images skipped: {not_webp}")
    print(f"❌ File not found in user folder: {not_found_in_user_folder}")
    print(f"⚠️  Other errors: {error_count}")
    print("=" * 60)

    total_skipped = already_in_uploads + already_in_database + not_webp + not_found_in_user_folder + error_count
    print(f"📊 Total skipped: {total_skipped}")
    print(f"📊 Success rate: {(migrated_count / total_posts * 100):.1f}%")
    print("=" * 60)

    if migrated_count > 0:
        print("🎉 Migration completed successfully!")
        print("📝 Post image fields have been updated with file URLs")
        if already_in_uploads > 0:
            print(f"📁 {already_in_uploads} files were already in uploads folder")
        if already_in_database > 0:
            print(f"🗄️  {already_in_database} files were already in database")
    else:
        print("⚠️  No files were migrated. Check the logs above for details.")


